import{_ as a}from"./chunks/architecture.Cs8uKTTN.js";import{_ as o,o as i,c as r,a2 as s}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"Arquitectura del sistema","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/dev-guide/architecture.md","filePath":"es-ES/dev-guide/architecture.md","lastUpdated":1787586465000}'),n={name:"es-ES/dev-guide/architecture.md"};function d(t,e,c,l,u,p){return i(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="arquitectura-del-sistema" tabindex="-1">Arquitectura del sistema <a class="header-anchor" href="#arquitectura-del-sistema" aria-label="Permalink to &quot;Arquitectura del sistema&quot;">​</a></h1><p>Lertaro está construido sobre un modelo de aislamiento multiproceso y una arquitectura modular por capas, garantizando búsquedas en submilisegundos y una profunda integración de escritorio con el máximo nivel de seguridad y estabilidad.</p><p><img src="'+a+'" alt="Diagrama de arquitectura de Lertaro"></p><h2 id="_1-modelo-de-aislamiento-de-tres-procesos" tabindex="-1">1. Modelo de aislamiento de tres procesos <a class="header-anchor" href="#_1-modelo-de-aislamiento-de-tres-procesos" aria-label="Permalink to &quot;1. Modelo de aislamiento de tres procesos&quot;">​</a></h2><p>Para evitar que el fallo de un único componente provoque el cierre del sistema y para limitar los privilegios elevados al mínimo indispensable, la ejecución se divide en tres procesos independientes:</p><h3 id="_1-servicio-de-indexacion-en-segundo-plano-lertaro-service" tabindex="-1">1. Servicio de indexación en segundo plano (<code>Lertaro.Service</code>) <a class="header-anchor" href="#_1-servicio-de-indexacion-en-segundo-plano-lertaro-service" aria-label="Permalink to &quot;1. Servicio de indexación en segundo plano (`Lertaro.Service`)&quot;">​</a></h3><ul><li><strong>Identidad</strong>: Se ejecuta de forma continua como un servicio de Windows con la cuenta <code>LocalSystem</code>.</li><li><strong>Responsabilidades</strong>: Indexación del sistema de archivos y seguimiento de cambios. Lee los diarios USN y las tablas $MFT de volúmenes NTFS / ReFS; monitoriza eventos de cambio en FAT32 / exFAT; escanea y almacena en caché recursos compartidos SMB / NAS.</li><li><strong>Seguridad y rendimiento</strong>: Al ejecutarse en el nivel SYSTEM, accede a los metadatos de los volúmenes sin mostrar cuadros de UAC, respondiendo a la aplicación en modo usuario mediante tuberías con nombre de alta velocidad sin otorgar privilegios innecesarios a la interfaz.</li></ul><h3 id="_2-aplicacion-de-interaccion-con-el-usuario-lertaro-app" tabindex="-1">2. Aplicación de interacción con el usuario (<code>Lertaro.App</code>) <a class="header-anchor" href="#_2-aplicacion-de-interaccion-con-el-usuario-lertaro-app" aria-label="Permalink to &quot;2. Aplicación de interacción con el usuario (`Lertaro.App`)&quot;">​</a></h3><ul><li><strong>Identidad</strong>: Aplicación de escritorio WPF estándar en modo usuario aislada por sesión.</li><li><strong>Responsabilidades</strong>: Aloja la barra de búsqueda rápida, la ventana principal, el Centro de configuración, la gestión de atajos globales, el menú de acciones (<code>Ctrl+O</code>) y las vistas previas de QuickLook.</li><li><strong>Puente IPC y alojamiento CLI</strong>: Se comunica con el servicio mediante tuberías con nombre bidireccionales (<code>Core.Services.SearchService</code>). También aloja una tubería dedicada por usuario (<code>AppSearchPipeService</code>), lo que permite a la utilidad <code>lff</code> reutilizar las tablas de memoria y plugins de la aplicación sin reinicializaciones independientes.</li></ul><h3 id="_3-proceso-de-interceptacion-de-teclado-y-adaptadores-lertaro-service-hook" tabindex="-1">3. Proceso de interceptación de teclado y adaptadores (<code>Lertaro.Service --hook</code>) <a class="header-anchor" href="#_3-proceso-de-interceptacion-de-teclado-y-adaptadores-lertaro-service-hook" aria-label="Permalink to &quot;3. Proceso de interceptación de teclado y adaptadores (`Lertaro.Service --hook`)&quot;">​</a></h3><ul><li><strong>Identidad</strong>: Proceso auxiliar con privilegios adecuados iniciado por el servicio de Windows según demanda.</li><li><strong>Responsabilidades</strong>: Aloja los enlaces de teclado de bajo nivel y la escucha global de eventos de ratón.</li><li><strong>Omisión de UIPI y aislamiento de fallos</strong>: El aislamiento de privilegios de interfaz (UIPI) de Windows impide que procesos de menor integridad envíen mensajes a ventanas elevadas. Al ejecutar los adaptadores de ventana (<a href="./sdk/system-adapters.html"><code>IActivePathCollector</code>, <code>IFileDialogAdapter</code>, <code>IInlineSearchAdapter</code></a>) dentro de este proceso, Lertaro se integra sin problemas en instancias de Explorador y diálogos ejecutados como Administrador. Además, los fallos en los enlaces de teclado no afectan a la aplicación principal.</li></ul><h2 id="_2-libreria-central-compartida-lertaro-core" tabindex="-1">2. Librería central compartida (<code>Lertaro.Core</code>) <a class="header-anchor" href="#_2-libreria-central-compartida-lertaro-core" aria-label="Permalink to &quot;2. Librería central compartida (`Lertaro.Core`)&quot;">​</a></h2><p><code>Lertaro.Core</code> es referenciada conjuntamente por los tres procesos, e incluye:</p><ul><li><strong>Motor de coincidencia difusa fzf (<code>Core/SearchIndex/Fzf/*</code>)</strong>: Coincidencia de caracteres dispersos, puntuación y cálculo de máscaras de resaltado optimizados, junto con <code>SearchQueryParser</code> para letras de unidad y patrones de ruta.</li><li><strong>Índice columnar en memoria (<code>Core/IndexV2/*</code>)</strong>: Instantáneas columnares proyectadas en memoria combinadas con una capa de deltas en memoria para búsquedas instantáneas entre cientos de millones de archivos.</li><li><strong>Protocolos binarios IPC</strong>: Estructuras de mensajes serializadas (<code>SearchRequestMessage</code>) para transferencias interproceso sin copias redundantes.</li><li><strong>Sistema de registro unificado (<code>Logger</code>)</strong>: Emite registros hacia <code>service.log</code>, <code>app.log</code> y <code>hook.log</code>, accesibles de forma centralizada en el visor de registros.</li></ul><h2 id="_3-posicion-del-sistema-de-plugins-en-la-arquitectura" tabindex="-1">3. Posición del sistema de plugins en la arquitectura <a class="header-anchor" href="#_3-posicion-del-sistema-de-plugins-en-la-arquitectura" aria-label="Permalink to &quot;3. Posición del sistema de plugins en la arquitectura&quot;">​</a></h2><p>Todos los plugins se compilan contra <code>Lertaro.PluginSdk</code> y se cargan dinámicamente al iniciar <code>Lertaro.App</code>:</p><ul><li><strong>Comunicación sin privilegios</strong>: Los plugins interactúan exclusivamente con el proceso App. Si un plugin requiere indexar carpetas personalizadas, delega la petición mediante <code>DirectoryIndexerService</code>.</li><li><strong>Mecanismo de doble carga</strong>: Los componentes estándar se ejecutan en App; los adaptadores de ventanas y diálogos (<code>IActivePathCollector</code>, etc.) se cargan adicionalmente en el proceso Hook para interactuar con ventanas elevadas.</li></ul>',17)])])}const v=o(n,[["render",d]]);export{h as __pageData,v as default};
